import csv,random
r=list(csv.DictReader(open('data/holdout_scores.csv')))
y=[int(x['churned']) for x in r]
print(len(r),sum(y),sum(y)/len(y), len(set(x['customer_id'] for x in r)))
def auc(s):
    p=sorted(zip(s,y));rk=0;n1=sum(y);n0=len(y)-n1;t=0
    for i,(a,b) in enumerate(p,1):
        if b:t+=i
    return (t-n1*(n1+1)/2)/(n1*n0)
S={m:[float(x[m]) for x in r] for m in('model_a_score','model_b_score')}
def topk(s,k=500):
    idx=sorted(range(len(s)),key=lambda i:-s[i])[:k];return sum(y[i] for i in idx)
for m,s in S.items(): print(m,'auc',round(auc(s),4),'hits@500',topk(s),'ties',len(s)-len(set(s)))
random.seed(0);d=[]
for _ in range(1000):
    ix=[random.randrange(len(y)) for _ in y]
    def t(s):
        o=sorted(ix,key=lambda i:-s[i])[:500];return sum(y[i] for i in o)
    d.append(t(S['model_a_score'])-t(S['model_b_score']))
d.sort();print('A-B hits diff 95% CI',d[25],d[975],sum(d)/1000)
